begin;
alter table public.sucursales add column costo_envio numeric(12,2) not null default 0 check(costo_envio>=0),
 add column apertura time not null default '00:00',add column cierre time not null default '23:59:59',
 add column dias_entrega text not null default '1,2,3,4,5,6,7' check(dias_entrega ~ '^[1-7](,[1-7])*$'),
 add constraint horario_valido check(apertura<cierre);
alter table public.pedidos add column subtotal numeric(14,2),add column costo_envio numeric(12,2) not null default 0,
 add column descuento_cupon numeric(12,2) not null default 0,
 add column estado_pago text not null default 'PENDIENTE' check(estado_pago in ('PENDIENTE','PAGADO','RECHAZADO','REEMBOLSO_PENDIENTE')),
 add column pago_referencia varchar(150),add column receta_estado text not null default 'NO_REQUIERE' check(receta_estado in ('NO_REQUIERE','PENDIENTE','APROBADA','RECHAZADA')),
 add column receta_path text, add column expira_en timestamptz;
update public.pedidos set subtotal=total,estado_pago=case when estado='ENTREGADO' then 'PAGADO' else 'PENDIENTE' end;
create table public.cupones(id_cupon bigint generated by default as identity primary key,codigo varchar(30) unique not null check(codigo ~ '^[A-Z0-9-]{3,30}$'),
 porcentaje numeric(5,2) not null check(porcentaje>0 and porcentaje<=90),minimo numeric(12,2) not null default 0 check(minimo>=0),
 desde date,hasta date,max_usos integer not null default 100 check(max_usos>0),usos integer not null default 0,activo boolean not null default true,
 check(desde is null or hasta is null or desde<=hasta));
create table public.contenidos(id_contenido bigint generated by default as identity primary key,tipo text not null check(tipo in ('MISION','VISION','PROGRAMA','FAQ')),
 titulo varchar(150) not null,cuerpo varchar(4000) not null,orden integer not null default 0,activo boolean not null default true);
insert into public.contenidos(tipo,titulo,cuerpo,orden) values
 ('MISION','Hacer más sencillo el acceso al cuidado.','Acercar productos de farmacia a las personas mediante información clara, atención en sucursal y opciones de entrega.',1),
 ('VISION','Ser una farmacia cercana, también en lo digital.','Conectar la atención local con herramientas digitales para consultar productos, organizar compras y seguir pedidos.',2),
 ('PROGRAMA','Bienestar en familia','Consulta presentaciones y disponibilidad para organizar las compras del hogar. Confirma las actividades disponibles con tu sucursal.',1),
 ('PROGRAMA','Compras habituales','Localiza productos de tu compra habitual y coordina su entrega. Contacta al personal para conocer la atención disponible.',2),
 ('PROGRAMA','Uso responsable del servicio','Conoce los requisitos de receta y las opciones de atención antes de realizar tu pedido. No sustituye una consulta médica.',3),
 ('FAQ','¿Cómo puedo pagar?','Elige efectivo, tarjeta o transferencia al recibir. La farmacia registra el pago cuando lo recibe. No se realizan cobros automáticos en el sitio.',1),
 ('FAQ','¿Puedo pedir medicamentos con receta?','Sí. Adjunta una imagen de tu receta al finalizar la compra. El personal debe revisarla y aprobarla antes de preparar tu pedido.',2),
 ('FAQ','¿Cómo cancelo mi pedido?','Abre el seguimiento con tu código privado. Puedes cancelar antes del despacho si el pago sigue pendiente. Para otras situaciones contacta a la sucursal.',3),
 ('FAQ','¿Dónde veo mis compras anteriores?','El historial conserva los códigos de pedidos en este navegador. Cada código permite consultar exclusivamente ese pedido.',4);
do $$ declare tab text; begin foreach tab in array array['cupones','contenidos'] loop
 execute format('alter table public.%I enable row level security',tab);
 execute format('grant select,insert,update on public.%I to authenticated',tab);
 execute format('grant all on public.%I to service_role',tab);
 execute format('grant usage,select on sequence %s to authenticated,service_role',pg_get_serial_sequence('public.'||tab,'id_'||case when tab='cupones' then 'cupon' else 'contenido' end));
 execute format('create policy administracion on public.%I for all to authenticated using(privado.permitido(array[''ADMIN''])) with check(privado.permitido(array[''ADMIN'']))',tab);
 end loop;end $$;
create function public.contenido_publico() returns jsonb language sql stable security definer set search_path=pg_catalog,public as $$
 select coalesce(jsonb_agg(jsonb_build_object('id',id_contenido,'tipo',tipo,'titulo',titulo,'cuerpo',cuerpo) order by orden,id_contenido),'[]'::jsonb) from public.contenidos where activo;
$$;
revoke all on function public.contenido_publico() from public;
grant execute on function public.contenido_publico() to anon,authenticated;
create or replace function public.crear_pedido_portal(p_datos jsonb,p_clave uuid,p_token_hash text) returns jsonb
language plpgsql security definer set search_path=pg_catalog,public as $$
declare anterior privado.pedidos_portal; cliente bigint; resultado jsonb; suc public.sucursales; cupon public.cupones;
 rx boolean; monto numeric; rebaja numeric:=0; pedido_id bigint; local_now timestamp:=now() at time zone 'America/Guatemala';
begin
 perform pg_advisory_xact_lock(hashtextextended(p_clave::text,0));
 select * into anterior from privado.pedidos_portal where clave=p_clave;
 if found then
  if anterior.solicitud<>p_datos or anterior.token_hash<>p_token_hash then raise exception 'La clave ya corresponde a otro pedido' using errcode='P0001';end if;
  return anterior.respuesta;
 end if;
 select * into suc from public.sucursales where id_sucursal=(p_datos->>'id_sucursal')::bigint for share;
 if local_now::time not between suc.apertura and suc.cierre or not extract(isodow from local_now)::int::text=any(string_to_array(suc.dias_entrega,',')) then
  raise exception 'La sucursal está fuera del horario de pedidos' using errcode='P0001';end if;
 select exists(select 1 from jsonb_array_elements(p_datos->'items') i join public.medicamentos m on m.id_medicamento=(i->>'id_medicamento')::bigint where m.requiere_receta) into rx;
 if rx and (coalesce(p_datos->>'receta_path','')='' or split_part(p_datos->>'receta_path','/',1)<>p_token_hash) then
  raise exception 'Adjunta una receta para validación del personal' using errcode='P0001';end if;
 insert into public.clientes(codigo,nombre,apellido,telefono,direccion,email) values('WEB-'||substr(replace(p_clave::text,'-',''),1,24),p_datos->>'nombre',p_datos->>'apellido',p_datos->>'telefono',p_datos->>'direccion_entrega',nullif(p_datos->>'email','')) returning id_cliente into cliente;
 resultado:=privado.pedido_portal(p_datos||jsonb_build_object('id_cliente',cliente,'canal','PORTAL','receta_referencia',case when rx then 'PENDIENTE_VALIDACION' else null end));
 pedido_id:=(resultado->>'id_pedido')::bigint; monto:=(resultado->>'total')::numeric;
 if coalesce(p_datos->>'cupon','')<>'' then
  select * into cupon from public.cupones where codigo=p_datos->>'cupon' for update;
  if not found or not cupon.activo or cupon.usos>=cupon.max_usos or monto<cupon.minimo or (cupon.desde is not null and cupon.desde>local_now::date) or (cupon.hasta is not null and cupon.hasta<local_now::date) then
   raise exception 'Cupón inválido, agotado o no aplicable al subtotal' using errcode='P0001';end if;
  rebaja:=round(monto*cupon.porcentaje/100,2);update public.cupones set usos=usos+1 where id_cupon=cupon.id_cupon;
 end if;
 update public.pedidos set subtotal=monto,costo_envio=suc.costo_envio,descuento_cupon=rebaja,total=monto+suc.costo_envio-rebaja,
  receta_estado=case when rx then 'PENDIENTE' else 'NO_REQUIERE' end,receta_path=p_datos->>'receta_path',expira_en=now()+interval '2 hours' where id_pedido=pedido_id;
 resultado:=resultado||jsonb_build_object('subtotal',monto,'costo_envio',suc.costo_envio,'descuento_cupon',rebaja,'total',monto+suc.costo_envio-rebaja,'receta_estado',case when rx then 'PENDIENTE' else 'NO_REQUIERE' end);
 insert into privado.pedidos_portal(clave,token_hash,solicitud,id_pedido,respuesta) values(p_clave,p_token_hash,p_datos,pedido_id,resultado);
 return resultado;
end $$;
-- El estado operativo no avanza sin receta aprobada o pago confirmado.
create function privado.control_pedido_portal() returns trigger language plpgsql set search_path=pg_catalog,public as $$
begin
 if old.canal='PORTAL' and old.expira_en is not null then
  if new.estado in ('PREPARANDO','EN_CAMINO','ENTREGADO') and new.receta_estado not in ('NO_REQUIERE','APROBADA') then raise exception 'Primero valida la receta' using errcode='P0001';end if;
  if new.estado='ENTREGADO' and new.estado_pago<>'PAGADO' then raise exception 'Confirma el pago recibido antes de entregar' using errcode='P0001';end if;
  if new.estado in ('CANCELADO','DEVUELTO') and old.estado_pago='PAGADO' then new.estado_pago:='REEMBOLSO_PENDIENTE';end if;
 end if;
 if new.estado='ENTREGADO' then new.estado_pago:='PAGADO';end if;
 return new;
end $$;
create trigger control_portal before update on public.pedidos for each row execute function privado.control_pedido_portal();
create function public.gestionar_pedido_portal(p_id bigint,p_accion text,p_datos jsonb default '{}') returns jsonb
language plpgsql security definer set search_path=pg_catalog,public as $$
declare ped public.pedidos;
begin
 select * into ped from public.pedidos where id_pedido=p_id for update;
 if not found then raise exception 'Pedido no encontrado' using errcode='P0002';end if;
 perform privado.exigir(array['GERENTE','VENDEDOR'],ped.id_sucursal);
 if p_accion='receta' then
  if ped.estado<>'PENDIENTE' or ped.receta_estado not in ('PENDIENTE','RECHAZADA') or p_datos->>'estado' not in ('APROBADA','RECHAZADA') then raise exception 'No se puede validar esta receta' using errcode='P0001';end if;
  update public.pedidos set receta_estado=p_datos->>'estado',receta_referencia=case when p_datos->>'estado'='APROBADA' then 'VALIDADA_POR_'||auth.uid()::text else receta_referencia end where id_pedido=p_id;
 elsif p_accion='pago' then
  if ped.estado<>'EN_CAMINO' or ped.estado_pago='PAGADO' or p_datos->>'estado' not in ('PAGADO','RECHAZADO') then raise exception 'El pago se registra al recibir, con el pedido en camino' using errcode='P0001';end if;
  if ped.metodo_pago<>'EFECTIVO' and coalesce(trim(p_datos->>'referencia'),'')='' then raise exception 'Referencia del cobro obligatoria' using errcode='22023';end if;
  update public.pedidos set estado_pago=p_datos->>'estado',pago_referencia=p_datos->>'referencia' where id_pedido=p_id;
  if p_datos->>'estado'='PAGADO' then perform privado.estado_pedido(jsonb_build_object('id_pedido',p_id,'estado','ENTREGADO'));end if;
 else raise exception 'Acción inválida' using errcode='22023';end if;
 return jsonb_build_object('id_pedido',p_id,'accion',p_accion);
end $$;
revoke all on function public.gestionar_pedido_portal(bigint,text,jsonb) from public,anon;
grant execute on function public.gestionar_pedido_portal(bigint,text,jsonb) to authenticated;
create function public.cancelar_pedido_portal(p_token_hash text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public as $$
declare ped public.pedidos; r record;
begin
 select p.* into ped from public.pedidos p join privado.pedidos_portal t using(id_pedido) where t.token_hash=p_token_hash for update of p;
 if not found then raise exception 'Pedido no encontrado' using errcode='P0002';end if;
 if ped.estado='CANCELADO' then return jsonb_build_object('estado','CANCELADO');end if;
 if ped.estado not in ('PENDIENTE','PREPARANDO') or ped.estado_pago='PAGADO' then raise exception 'El pedido ya no se puede cancelar desde el portal. Contacta a la sucursal.' using errcode='P0001';end if;
 perform privado.bloquear_stock(ped.id_sucursal);
 for r in select * from public.reservas_pedido where id_pedido=ped.id_pedido loop update public.inventario set reservado=reservado-r.cantidad where id_inventario=r.id_inventario;end loop;
 update public.pedidos set estado='CANCELADO',nota_estado='Cancelado desde portal' where id_pedido=ped.id_pedido;
 return jsonb_build_object('estado','CANCELADO');
end $$;
revoke all on function public.cancelar_pedido_portal(text) from public,anon,authenticated;
grant execute on function public.cancelar_pedido_portal(text) to service_role;
create function public.expirar_pedidos_portal() returns integer language plpgsql security definer set search_path=pg_catalog,public as $$
declare r record; n integer:=0;
begin
 for r in select t.token_hash from privado.pedidos_portal t join public.pedidos p using(id_pedido) where p.estado='PENDIENTE' and p.estado_pago<>'PAGADO' and p.expira_en<now() order by p.id_pedido for update of p skip locked loop
  perform public.cancelar_pedido_portal(r.token_hash);n:=n+1;
 end loop;return n;
end $$;
revoke all on function public.expirar_pedidos_portal() from public,anon,authenticated;
grant execute on function public.expirar_pedidos_portal() to service_role;
-- Extiende el seguimiento sin divulgar dirección, teléfono personal ni archivos privados.
do $$ declare definition text;begin
 definition:=pg_get_functiondef('public.seguir_pedido_portal(text)'::regprocedure);
 definition:=replace(definition,'''metodo_pago'',p.metodo_pago,','''estado_pago'',p.estado_pago,''receta_estado'',p.receta_estado,''costo_envio'',p.costo_envio,''subtotal'',p.subtotal,''descuento_cupon'',p.descuento_cupon,''expira_en'',p.expira_en,''metodo_pago'',p.metodo_pago,');execute definition;
end $$;
commit;
